-- Generated by scripts/export_knowledge_base.py; additive phase 7, no embedding/vector tables.
-- Apply 001/002/003 first with workers stopped. Revisions preserve contract-v1 sources/evidence.

CREATE TABLE IF NOT EXISTS `${PROJECT_ID}.${DATASET}.knowledge_revisions` (
  `schema_version` STRING NOT NULL,
  `revision_id` STRING NOT NULL,
  `knowledge_id` STRING NOT NULL,
  `version` INT64 NOT NULL,
  `snapshot_id` STRING NOT NULL,
  `processing_key` STRING NOT NULL,
  `title` STRING NOT NULL,
  `claims` JSON NOT NULL,
  `evidence_link_ids` ARRAY<STRING>,
  `evidence_bindings` JSON NOT NULL,
  `missing_information` ARRAY<STRING>,
  `extraction_version` STRING NOT NULL,
  `input_fingerprint` STRING NOT NULL,
  `content_hash` STRING NOT NULL,
  `review_status` STRING NOT NULL,
  `review_sequence` INT64 NOT NULL,
  `reviewed_by` STRING,
  `review_note` STRING,
  `reviewed_at` TIMESTAMP,
  `created_at` TIMESTAMP NOT NULL
)
CLUSTER BY revision_id;

CREATE TABLE IF NOT EXISTS `${PROJECT_ID}.${DATASET}.knowledge_heads` (
  `schema_version` STRING NOT NULL,
  `knowledge_id` STRING NOT NULL,
  `latest_revision_id` STRING NOT NULL,
  `latest_version` INT64 NOT NULL
)
CLUSTER BY knowledge_id;

CREATE TABLE IF NOT EXISTS `${PROJECT_ID}.${DATASET}.knowledge_builds` (
  `schema_version` STRING NOT NULL,
  `build_id` STRING NOT NULL,
  `revision_id` STRING NOT NULL,
  `input_fingerprint` STRING NOT NULL
)
CLUSTER BY build_id;

CREATE TABLE IF NOT EXISTS `${PROJECT_ID}.${DATASET}.knowledge_review_events` (
  `schema_version` STRING NOT NULL,
  `event_id` STRING NOT NULL,
  `revision_id` STRING NOT NULL,
  `sequence` INT64 NOT NULL,
  `previous_status` STRING NOT NULL,
  `status` STRING NOT NULL,
  `reviewer` STRING NOT NULL,
  `note` STRING NOT NULL,
  `reviewed_at` TIMESTAMP NOT NULL
)
CLUSTER BY event_id;
